def save(suffix,obj):
    Path(str(PREFIX)+suffix).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

if __name__=='__main__':
    proposals=[]
    for n,(title,point,tags,compared,reason,subject,concept,keywords) in enumerate(rows,1102):
        proposals.append(dict(id=str(n),category='chemie' if n<1118 else 'sport' if n<1128 else 'kinematografie',knowledge=dict(idea=f'idea-{n}',point=point,tags=tags.split(','),type='principle'),compared_ids=compared.split(','),reason=reason,verdict='accept'))
    save('-plan.json',dict(snapshot=SNAP,catalog_reviewed=SNAP,proposals=proposals))
    searches=[]
    for p,r in zip(proposals,rows):
        result=json.loads(subprocess.check_output(['python','scripts/post-knowledge.py','search','--query',r[0]+' '+r[1],'--tags',','.join(p['knowledge']['tags']),'--limit','5'],cwd=ROOT,encoding='utf-8'))
        searches.append(dict(id=p['id'],query=r[0]+' '+r[1],results=result))
    save('-searches.json',searches)
    print(json.dumps([dict(id=s['id'],matches=[(r['id'],r['point']) for r in s['results']['results']]) for s in searches],ensure_ascii=False))
